INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 1, '一名中年商人独自坐在深色木书房里，灯下摊开厚账本与金秤，神情严肃地核对数字，窗外城市灯火昏黄。', 'data/image_library/finance/1.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 2, '欧式银行大厅空无一人，长桌上堆着金币、契约与关着的铁箱，大理石柱投出冷硬的阴影。', 'data/image_library/finance/2.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 3, '黎明的欧洲广场上，一名衣着朴素的男子把木箱货物摊在石板地上，路人侧目，他仍挺直腰板守着摊位。', 'data/image_library/finance/3.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 4, '乡间砖窑作坊内，几名工人围着木工台赶制成堆的鞋履与扣件，窗外麦田与烟囱并立，光线从高窗打下。', 'data/image_library/finance/4.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 5, '一名穿深色大衣的男子提着皮箱走出庄严的政府式石砌大楼，回望门廊里仍坐着喝茶读报的人群，台阶洒满午后阳光。', 'data/image_library/finance/5.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 6, '夜晚书房里，一名学者俯身在巨大世界地图上用红线连接港口与城市，桌上堆着信件、航海图与熄灭的蜡烛。', 'data/image_library/finance/6.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 7, '都市咖啡馆里，多数人低头翻旧报纸，唯有角落一位年轻人凝视掌心一块小巧的黑玻璃装置，窗外车灯如潮。', 'data/image_library/finance/7.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 8, '废弃工厂车间中央，一台巨大的老式蒸汽机被拆开重装，地上铺满齿轮与图纸，远处高炉已熄，晨光从破屋顶漏下。', 'data/image_library/finance/8.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 9, '一间简朴阁楼工作室里，一名普通人独自坐在长桌前，左右摆满文件、产品样品与空白画布，像一个人撑起整家公司。', 'data/image_library/finance/9.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 10, '庄园书房近景：一只戴金表的手将羽毛笔搭上黄铜机械杠杆，杠杆另一端连着一排自动书写的羽管，窗外雷雨将至。', 'data/image_library/finance/10.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 11, '十八岁生日的欧式家庭客厅里，一名刚成年的年轻男子坐在父母之间，桌上没有蛋糕礼盒，只有一只装着现金的信封与一份等待签字的投资账户文件。', 'data/image_library/finance/11.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 12, '深色木桌上并排放着一部已经破旧开裂的旧手机和一只装着金币的玻璃罐，手机蒙尘熄屏，玻璃罐后方则延伸出越来越高的金币堆。', 'data/image_library/finance/12.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 13, '一名三十多岁的男子站在阁楼储物间里，手中拿着一部无法开机的老旧手机，身旁木箱堆满淘汰的电子产品，他神情复杂地看着这些昔日昂贵的物件。', 'data/image_library/finance/13.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 14, '庄严银行办公室里，一名父亲带着十八岁的儿子坐在黄铜柜台前，银行职员递来账户文件，年轻人把一小叠现金放到桌上，父亲在旁安静注视。', 'data/image_library/finance/14.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 15, '多年后的书房中，一名成年男子意外翻出尘封的旧账户册，打开厚重账本后愣在桌前，身旁从小钱袋逐渐堆成一座金币小山。', 'data/image_library/finance/15.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 16, '古典书房长桌上整齐排列着四十多个小钱袋，每只钱袋大小相同，沿着桌面向远处延伸，尽头是一只巨大保险箱与高高堆起的金币。', 'data/image_library/finance/16.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 17, '一间老式家庭餐厅里，父母把存折和硬币谨慎地锁进木柜，年轻人坐在另一端翻看金融书籍，墙上的旧钟与褪色日历强调着两个时代的距离。', 'data/image_library/finance/17.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 18, '昏暗交易大厅里，一群西装商人围着复杂行情纸张争论不休，画面另一侧一名普通年轻人没有参与争抢，只把钱稳定投入一只代表整个市场的巨大篮筐。', 'data/image_library/finance/18.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 19, '每月同一天，一只戴普通腕表的手把相同数量的硬币投入桌上的木制投资箱，窗外季节从春夏渐渐变化到秋冬，桌边报纸始终没有被打开。', 'data/image_library/finance/19.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 20, '夕阳下的庄园书房里，一名中年男子把一个小型投资账户册交给刚毕业的年轻男孩，男孩低头认真查看，窗外一条漫长道路通向远处被阳光照亮的城市。', 'data/image_library/finance/20.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 21, '昏黄灯光下的老式家族餐厅里，一名二十岁的年轻男子独自坐在长桌尽头，墙上挂着三代祖辈的黑白肖像，桌前摊着账本、硬币与一只刚开始积累的小钱袋。', 'data/image_library/finance/21.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 22, '清晨的乡村与城市交界处，农民在田地里弯腰劳作，工人在工厂门口排队上班，小商贩推着木车叫卖，所有人都在用双手换取当天的收入。', 'data/image_library/finance/22.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 23, '一名年轻男子站在没有土地和厂房的简朴书房里，桌上只有几本书、一只存钱罐与投资文件，窗外远处巨大的农场和工厂逐渐隐入薄雾。', 'data/image_library/finance/23.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 24, '古典图书馆中，一名白发投资家安静坐在皮椅里，面前棋桌上的棋子多年未动，壁炉旁的长钟缓慢摆动，窗外四季景色仿佛在时间中交替。', 'data/image_library/finance/24.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 25, '深色木书桌前，一名年轻人准备做出选择，桌面一侧放着昂贵皮鞋、手表和精致酒具，另一侧放着书籍、课程资料、证书与一只投资钱箱，他停下手认真思考。', 'data/image_library/finance/25.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 26, '华丽鞋店的玻璃柜前，一名年轻男子拿着半个月收入换来的昂贵限量鞋，画面另一侧几年后的同一双鞋已经氧化褪色，被遗忘在满是灰尘的阁楼角落。', 'data/image_library/finance/26.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 27, '安静书房中，一名年轻人伏案阅读专业书籍，桌边摆着课程资料和刚取得的证书，远处另一张桌上金币与文件逐渐堆高，象征知识和本金同时积累。', 'data/image_library/finance/27.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 28, '古典实验室般的书房里，两只钱袋形成鲜明对比，一只被剪开后金币散落消失，另一只连接着精密黄铜机械，持续将小金币送入越来越大的储蓄箱。', 'data/image_library/finance/28.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 29, '漫长石阶从山脚延伸至高处，一名二十岁的年轻人推着很小的雪球缓慢向上，远处一名三十岁的男子才刚开始起步，而山顶已经堆着巨大的雪球。', 'data/image_library/finance/29.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 30, '多年跨度的城市街景中，一名男子始终把固定的钱投入小木箱，身旁同龄人陆续换上新汽车、提着旅行箱远行，他的木箱起初不起眼，却在远处逐渐变成庞大的金币堆。', 'data/image_library/finance/30.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 31, '三十岁左右的城市街道上，一对新人从婚礼马车旁走过，有人签下房屋契约，有人提走新车，而一名男子站在街角抱着多年积累的账本，身后巨大的金币雪球已经明显超过众人。', 'data/image_library/finance/31.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 32, '长桌上四十只相同的小钱袋按年份整齐排开，每只都装着少量硬币，桌子尽头却堆起远超本金规模的金币山，一名老人站在尽头查看最终积累。', 'data/image_library/finance/32.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 33, '同一间书房里，两条平行长桌展示不同的人生起点，一侧年轻人早早开始堆积金币，另一侧男子十年后才开始，几十年后两端的财富规模形成巨大差距。', 'data/image_library/finance/33.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 34, '餐厅、旅行车站和鞋柜里的消费场景像回忆般散落在画面四周，中央一名中年男子凝视空掉的钱袋，远处则是一座本可以属于他的巨大金币堆。', 'data/image_library/finance/34.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 35, '年轻男子在昏暗书房里把第一叠积蓄锁进厚重铁箱，铁箱上落着一把大锁，旁边虽然堆着房租账单和信用账单，他仍没有伸手打开铁箱。', 'data/image_library/finance/35.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 36, '普通出租屋里，一名年轻人白天伏案做本职工作，夜晚在另一张桌前完成副业，墙边小钱箱里的钞票一点点增加，生活用品却始终保持简单克制。', 'data/image_library/finance/36.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 37, '古典商店中央，一名男子面对两排物品做选择，一侧是汽车、珠宝与奢华衣物不断消耗金币，另一侧是出租房钥匙、书籍和投资凭证不断将金币送回他的口袋。', 'data/image_library/finance/37.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 38, '漫长山路上，一群年轻人追逐远处突然升空的金色烟火，只有一名男子低头稳稳推着雪球沿石路前进，身后的雪球已经在岁月中越来越大。', 'data/image_library/finance/38.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 39, '旧时代的昏暗农舍中，祖辈围着微弱油灯清点仅够生活的硬币，窗外是农田和简陋工棚；画面远处的新一代年轻人坐在明亮书房里，只用少量资金便能开始投资。', 'data/image_library/finance/39.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 40, '黎明时分，一名二十岁的年轻男子站在城市高处，手里握着第一枚投入资产的硬币，脚下道路通向银行、住宅、书房与远方城市，晨光照亮他迈出的第一步。', 'data/image_library/finance/40.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 41, '清晨的城市公寓里，一名三十岁左右的男子摘下领带，把公文包和工作证安静放进抽屉，随后独自坐到窗边书桌前，桌上只有笔记本、咖啡和一整年的空白日历。', 'data/image_library/finance/41.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 42, '深色书房里，一名年轻男子坐在投影幕前认真观看商业人物访谈和经济纪录影像，四周墙面贴着产业地图、市场图表与商业案例照片，桌上密密麻麻铺满手写笔记。', 'data/image_library/finance/42.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 43, '一张长桌上堆着数十本厚重经济书籍，一名男子没有逐本翻阅，而是坐在另一端观看一位资深商业学者在黑板前拆解复杂案例，身旁笔记已经浓缩成几页重点。', 'data/image_library/finance/43.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 44, '阁楼工作室里，一名男子站在巨大木桌前筛选不同创业方案，桌上摆着小型产品样品、物流包裹、电脑设备与投资文件，他最终把其中一个项目单独移到灯光最亮的位置。', 'data/image_library/finance/44.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 45, '古典更衣室与书房相连，一名已有稳定事业的男子整理合身西装、皮鞋和腕表，镜中形象干净克制，身后的书桌上摆着账本、合同和已经运转的生意文件。', 'data/image_library/finance/45.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 46, '豪华公寓中，一名富有男子穿着皱乱睡袍坐在杂乱沙发上，地面散落衣物与空酒杯，桌上的昂贵腕表和钱包被随意丢弃，窗外明亮城市与室内凌乱形成强烈反差。', 'data/image_library/finance/46.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 47, '拥挤办公室里，几十名职员在相同工位机械地处理文件，墙上时钟不断转动，一名男子从清晨坐到夜晚，窗外季节变化，但桌面和生活几乎没有任何改变。', 'data/image_library/finance/47.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 48, '安静住宅书房中，一名男子独自研究巨大的经济关系图，桌面连接着行业资料、成本账本、市场地图和商业模型，他用细线把不同信息逐渐串联成完整结构。', 'data/image_library/finance/48.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 49, '家中小型工作室里，一名普通人同时处理产品、包装、电脑订单和客户文件，墙边废纸篓里塞满失败方案，桌上则摆着一版又一版不断改进的新产品。', 'data/image_library/finance/49.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 50, '一年后的清晨，一名男子推开工作室大门站在阳光中，身后墙面挂满学习笔记、商业地图和迭代方案，桌上已有稳定运转的产品与账本，前方城市道路在晨光里向远处展开。', 'data/image_library/finance/50.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 51, '清晨的城市公寓里，一名年轻男子刚收到工资，把大部分现金放进上锁的木箱，只留下少量生活费在桌面，窗外上班人群正匆匆穿过街道。', 'data/image_library/finance/51.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 52, '繁忙办公室里，一名疲惫职员伏案工作到深夜，画面另一侧的商店橱窗里摆满新衣、皮鞋和奢侈品，他刚领到的钱仿佛沿着柜台重新流回商店。', 'data/image_library/finance/52.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 53, '一座巨大圆形工坊中，一名男子蒙着眼沿着木制转盘不断推磨，转盘外围依次摆着工资袋、购物袋和账单，每转一圈又重新回到工作的位置。', 'data/image_library/finance/53.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 54, '华丽百货商店里，一名年轻人提着新衣、鞋盒和精致皮包走出柜台，身后却拖着一条沉重铁链，铁链另一端牢牢连接着远处昏暗的办公桌。', 'data/image_library/finance/54.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 55, '同一间办公室跨越多年，一名男子从年轻到中年始终坐在相同工位，桌上文件越来越高，头发逐渐灰白，窗外晨昏交替而他仍在机械工作。', 'data/image_library/finance/55.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 56, '雨夜街头，一名刚下班的年轻人神情疲惫地站在明亮商店橱窗前，手里握着工资信封，橱窗中的新衣和商品十分诱人，远处出租屋窗口却堆着未付账单。', 'data/image_library/finance/56.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 57, '深色木桌上，一侧堆满崭新的鞋子、衣服和电子设备，另一侧只有不断增加的现金与储蓄箱，一扇写意般打开的房门在储蓄箱后方通向明亮的户外。', 'data/image_library/finance/57.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 58, '古典书房里，一位白发投资家坐在皮椅旁整理第一叠本金，桌上的小钱袋通过一套缓慢转动的黄铜齿轮连接到越来越大的金币堆，他安静等待而没有频繁操作。', 'data/image_library/finance/58.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 59, '石砌银行大厅里，一名年轻男子把一叠现金牢牢收进私人保险箱，旁边水槽中的硬币却随着流水不断冲走，形成存住与花光的鲜明对比。', 'data/image_library/finance/59.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 60, '昏暗办公室门口，一名西装男子平静地把辞职文件放在老板桌上，身后提着简单皮箱，手中握着厚实的储蓄账本，门外阳光照亮宽阔街道。', 'data/image_library/finance/60.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 61, '压抑的办公室里，其他职员低头忍受主管训斥，一名男子却从容合上文件起身离开，他的钱包和储蓄凭证安稳放在大衣内侧。', 'data/image_library/finance/61.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 62, '一名年轻人站在两条道路的岔口，一边通向灯火辉煌的商店、餐厅和娱乐场所，另一边较为朴素，却一路通向远方阳光下的自由庄园。', 'data/image_library/finance/62.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 63, '发薪日的银行柜台前，一名年轻男子刚拿到厚实工资信封，立刻将其中一半放入无法随意开启的储蓄箱，另一半才收进日常钱包。', 'data/image_library/finance/63.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 64, '普通公寓的餐桌上，男子正在认真核对生活支出，桌面只有简单食物和必要用品，身后的储蓄罐却随着月份推移逐渐换成更大的木箱。', 'data/image_library/finance/64.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 65, '巨大旧式磨坊里，一名年轻人停下不断转动的磨盘，将连接自己腰间的粗绳亲手解开，身后的工资袋没有再流向消费货架，而是整齐堆进木箱。', 'data/image_library/finance/65.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 66, '深夜书房中，一名年轻男子把每月积累的硬币投入黄铜机械装置，小齿轮带动更大的齿轮缓慢旋转，最终将更多金币送入远处的保险箱。', 'data/image_library/finance/66.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 67, '多年后的宽敞书房里，中年男子安静坐在窗边喝咖啡，桌上的投资账本与金币箱已经十分充实，而窗外办公室人群仍在清晨匆忙赶去上班。', 'data/image_library/finance/67.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 68, '百货商场中央，购物人群争相伸手拿取新鞋、服饰和精致商品，一名年轻男子却背对柜台离开，把未花出去的钱谨慎放入大衣口袋。', 'data/image_library/finance/68.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 69, '漫长时间轴般的石路从青年延伸到中年，道路两侧散落着早已破旧的衣服、鞋子和电子产品，而男子一路保存下来的钱袋最终汇聚成巨大的财富仓库。', 'data/image_library/finance/69.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 70, '黎明的巨大磨坊门前，一名男子走出阴暗厂房，把断开的绳索留在身后，手里提着装满多年积蓄的皮箱，前方开阔道路与晨光一直延伸到远方。', 'data/image_library/finance/70.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 71, '深色古典书房里，一名中年投资者独自坐在长桌前，桌面只摆着两枚棋子、一本厚账本和一小叠投资文件，四周堆满尚未打开的商业资料。', 'data/image_library/finance/71.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 72, '繁忙城市十字路口，一名年轻男子不停在不同商店、工厂和办公室之间奔跑，手里不断更换项目文件，脚边散落大量已经放弃的计划书。', 'data/image_library/finance/72.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 73, '老式交易大厅里，几十名交易员激烈挥舞订单，一名沉稳男子却安静坐在角落的皮椅上，双手交叠，没有碰桌上的任何买卖文件。', 'data/image_library/finance/73.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 74, '古典书房的木桌上摆着二十枚黄铜筹码，一名投资者拿起其中一枚反复端详，旁边摊开企业账本、产业地图和厚厚的研究笔记。', 'data/image_library/finance/74.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 75, '安静图书馆里，两位年长投资家多年如一日坐在壁炉旁阅读公司资料，墙边落地钟缓慢摆动，窗外从春天逐渐变成冬天。', 'data/image_library/finance/75.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 76, '金融危机中的华尔街街头一片混乱，人群抱着文件仓皇离开银行，一名白发投资者却站在石阶上冷静观察，手中紧握装满现金的皮箱。', 'data/image_library/finance/76.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 77, '昏暗银行会议室里，一名年长投资者把厚厚一叠资金文件推向桌对面的金融机构代表，窗外街道仍笼罩在危机的阴云之下。', 'data/image_library/finance/77.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 78, '繁华年代的城市大道上，一群年轻投机客驾驶豪华跑车驶过霓虹般明亮的金融街，路边不断有人举杯庆祝，空气中充满短暂繁荣的狂热。', 'data/image_library/finance/78.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 79, '多年后的废弃车库中，一辆曾经耀眼的豪华跑车蒙满厚厚灰尘，旁边散落破旧股票文件和空酒瓶，昔日主人已经不见踪影。', 'data/image_library/finance/79.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 80, '简洁明亮的食品工坊里，工人把糖浆装进一排玻璃瓶，一名投资者站在旁边查看生产流程，整个生意没有复杂机器，只有重复而稳定的产品。', 'data/image_library/finance/80.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 81, '老式杂货店柜台上整齐排列着相同的饮料玻璃瓶，店外街景从马车时代逐渐延伸到现代汽车时代，而柜台上的商品始终没有本质变化。', 'data/image_library/finance/81.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 82, '一名投资者站在两扇门前，一扇门后布满复杂机器、密集线路和难懂图纸，另一扇门后只有简单商店、商品与稳定排队的顾客，他坚定走向后者。', 'data/image_library/finance/82.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 83, '古典书房中，一名男子完成一笔投资后合上账本，把羽毛笔放回笔架，随后靠在皮椅上安静喝茶，桌上的投资文件多年没有再次翻动。', 'data/image_library/finance/83.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 84, '庭院中央一棵刚栽下的小树苗旁放着一只小钱袋，远处同一棵树随着四季和岁月不断长大，最终形成枝繁叶茂的巨大树冠。', 'data/image_library/finance/84.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 85, '漫长画廊中排列着二三十扇代表年份的窗户，一名年轻投资者从第一扇窗前缓慢走过，手中的小钱袋随着距离增加逐渐变成沉重的财富箱。', 'data/image_library/finance/85.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 86, '老式书房里，一份数十年前的投资凭证静静锁在玻璃柜中，柜子周围从少量硬币逐渐堆成几乎占满房间的金币山。', 'data/image_library/finance/86.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 87, '一名年轻男子躺在庄园树荫下安静休息，远处自动运转的水车不断把一枚枚金币送入仓库，他本人没有参与任何操作。', 'data/image_library/finance/87.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 88, '现代交易室里，一名焦虑男子一天数次冲到行情板前查看价格，桌上咖啡杯和揉皱的交易纸越来越多，他的表情随着价格变化不断紧张和兴奋。', 'data/image_library/finance/88.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 89, '深夜书房里，一名投资者不断在买入和卖出文件之间来回签字，桌边废纸篓塞满作废订单，原本整齐的钱袋也在一次次操作中逐渐减少。', 'data/image_library/finance/89.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 90, '平静书房中，一名年长投资者主动把行情报纸折起放进抽屉，只留下几份真正重要的企业报告，然后坐到窗边继续阅读。', 'data/image_library/finance/90.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 91, '巨大的钟表工坊内，一套黄铜机械自行缓慢运转，小齿轮带动大齿轮，将少量金币不断送向越来越大的保险箱，而主人只是站在远处观察。', 'data/image_library/finance/91.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 92, '一张古典棋桌上只剩下两个真正重要的棋子，一名投资者双手抱胸长时间观察棋局，桌边几十枚没有价值的棋子已经被全部收进木盒。', 'data/image_library/finance/92.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 93, '城市交易大厅内所有人都在快速奔跑、喊叫和交换文件，只有中央一名男子静止不动，手中牢牢握着自己长期持有的投资凭证。', 'data/image_library/finance/93.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 94, '雨夜的金融街上，人群争相从银行门口逃离，一名投资者撑着黑伞逆着人流缓慢走向银行大门，手里的皮箱装满准备投入的资金。', 'data/image_library/finance/94.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 95, '晴朗午后的商业街上，一家经营简单商品的老店顾客稳定进出，店铺两侧的新潮商店不断更换招牌和主人，只有这家老店始终保持原样。', 'data/image_library/finance/95.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 96, '庄园书房里，一名年轻投资者把一只小雪球放到窗台边，随后数十年的季节在窗外不断更替，最终院子里出现一颗远大于人的巨大雪球。', 'data/image_library/finance/96.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 97, '凌晨交易室内，一名疲惫男子被大量行情纸、时钟和交易订单包围，双手抱头坐在桌前，而窗外天色已经开始变亮。', 'data/image_library/finance/97.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 98, '安静的乡间庄园里，一名投资者合上厚厚的账本，把它锁进木柜，随后走出书房在花园散步，身后保险箱里的资产仍在稳定积累。', 'data/image_library/finance/98.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 99, '两条人生道路形成鲜明对比，一边是一名男子不停追逐飞舞的金融报纸和不断变化的机会，另一边是一名男子守着一棵缓慢长大的财富之树安静等待。', 'data/image_library/finance/99.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 100, '夕阳照进古典书房，一名白发投资者安静坐在窗边，桌上只有两份已经泛黄的长期投资凭证，身后巨大的书架与保险箱象征几十年积累，他没有再做任何动作。', 'data/image_library/finance/100.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 101, '黎明时分空无一人的欧式石板街道，湿润路面映着橱窗微光，远处钟楼轮廓清晰，没有人物、没有金币，只有城市刚醒来的冷空气。', 'data/image_library/finance/101.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 102, '高耸档案馆的铁制书架之间，一名中年女性学者推着木梯查阅厚卷宗，天窗打下细尘光柱，桌上只有索引卡片与放大镜，不见钱币。', 'data/image_library/finance/102.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 103, '暴雨中的银行大理石台阶上空无一人，成排黑伞被风吹歪弃在栏杆旁，积水倒映着庄严门楣，气氛冷硬而安静。', 'data/image_library/finance/103.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 104, '雾气未散的港口全景，起重机吊起木箱货柜，拖船犁开灰色水面，码头工人如蚁，远处仓库连成一条工业天际线。', 'data/image_library/finance/104.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 105, '大型火车站候车大厅里，旅客提着朴素行李在巨型时钟下交错走过，铁轨从拱门延伸向亮处，没有交易屏，只有出发与等待。', 'data/image_library/finance/105.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 106, '高山隘口的风雪小径上，一名旅行者停步俯瞰谷底小镇的灯火，两条盘山路一明一暗分向不同山谷，天空刚露出一线冷金色。', 'data/image_library/finance/106.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 107, '秋日果园里，农人把真实的苹果装进木箱，阳光穿过枝叶，地上是落叶而不是金属，远处谷仓门开着，一派可触摸的收成。', 'data/image_library/finance/107.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 108, '雨后黄昏的城市屋顶平台空无一人，晾衣绳、水箱与烟囱参差排列，远处灯火连成一条河，近处只剩积水和一块弃置的木椅。', 'data/image_library/finance/108.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 109, '石柱公证厅内，一名女性公证员与一对夫妇在长桌前核验无字封蜡契约，墙上是庄严纹章浮雕，光线来自高窗，场面克制正式。', 'data/image_library/finance/109.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 110, '普通厨房餐桌旁，一名年轻女性把菜金与账单分开放进两个陶罐，灶上只有简单炖锅，窗外是雨巷，没有奢侈品也没有金库。', 'data/image_library/finance/110.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 111, '大雪覆盖的欧式广场空无一人，喷泉结冰，长椅积着厚雪，街灯在雾里晕开一团暖黄，地面只有一行浅浅脚印通向远方拱廊。', 'data/image_library/finance/111.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 112, '室内菜市场里，一名中年女性摊主把新鲜蔬菜码进木箱，顾客提着布袋经过，顶棚投下斑驳天光，货架上是食物而不是金属。', 'data/image_library/finance/112.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 113, '旧城区一排联排住宅外搭满木脚手架，工人在半空砌砖，街上堆着沙袋与灰浆，新窗框尚未上玻璃，一派正在被重建的街区。', 'data/image_library/finance/113.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 114, '黄昏渡轮甲板上，旅客靠着栏杆看对岸灯火，船尾划开深色河水，没有人看行情，只有渡口与对岸城市缓缓靠近。', 'data/image_library/finance/114.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 115, '老式印刷工坊里，巨大滚筒正在送出空白报纸，工人检查油墨与纸卷，墙上挂钟滴答，纸面上没有任何可读文字。', 'data/image_library/finance/115.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 116, '秋日公园里，一名穿旧大衣的老年女性坐在长椅上喂鸽子，脚边只有普通纸袋，远处年轻情侣走过，她并不看他们。', 'data/image_library/finance/116.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 117, '玻璃温室中，一名女性园丁在苗床间记录植株，水珠凝在叶片上，身后是一排相同的幼苗，工具简单，阳光被玻璃切成格子。', 'data/image_library/finance/117.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 118, '夜晚工厂大门外，换班工人成群走出灯火通明的厂房，烟囱缓缓冒白烟，自行车靠在铁栅栏上，地面反着积水。', 'data/image_library/finance/118.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 119, '空荡教室里，一名女教师擦去黑板上的最后痕迹，只留下干净的深色板面，课桌整齐空着，窗外操场有几个模糊人影。', 'data/image_library/finance/119.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
INSERT INTO image_library(line, id, caption, image_path, created_at, updated_at) VALUES ('finance', 120, '石拱桥横跨灰色河流，一名行人独自走在桥心，两岸仓库与低矮屋顶延伸向雾里，天空低垂，桥上没有车辆。', 'data/image_library/finance/120.png', '2026-08-20T16:00:00Z', '2026-08-20T16:00:00Z');
