-- 恢复 0008 删除的通用图库 image_library，并回填财经存量镜头 1–120。
-- 只写入 image_library，不改 finance_generated_images。
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS image_library (
    line TEXT NOT NULL,
    id INTEGER NOT NULL,
    caption TEXT NOT NULL,
    image_path TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (line, id)
);

DELETE FROM image_library WHERE line = 'finance' AND id BETWEEN 1 AND 120;

